WITH matched_keys AS (SELECT product_id, order_id FROM order_items EXCEPT ALL SELECT product_id, order_id FROM order_items WHERE order_id = 6), verified AS (SELECT s.* FROM order_items s INNER JOIN matched_keys k ON s.product_id = k.product_id AND s.order_id = k.order_id) SELECT CASE WHEN unit_price >= 310 THEN 'HIGH' ELSE 'LOW' END AS unit_price_tier, AVG(unit_price) AS avg_unit_price, CORR(unit_price, quantity) AS corr_unit_price_quantity, ROUND(AVG(unit_price), 2) AS avg_unit_price_2 FROM verified GROUP BY 1
